from collections import Counter

# (user, item) clicks before the split date; later clicks are the test.
train = [("u1", "a"), ("u1", "b"), ("u2", "a"), ("u2", "c"), ("u3", "a"), ("u3", "b")]
test = {"u1": "c", "u2": "b", "u3": "d"}
catalog = {"a", "b", "c", "d", "e"}

popular = [i for i, _ in Counter(i for _, i in train).most_common()]   # baseline.

def collaborative(user):                      # items liked by similar users.
    mine = {i for u, i in train if u == user}
    similar = {u for u, i in train if i in mine and u != user}
    scores = Counter(i for u, i in train if u in similar and i not in mine)
    return [i for i, _ in scores.most_common()] or popular

for name, rec in [("popular", lambda u: popular), ("collab", collaborative)]:
    top2 = {u: [i for i in rec(u) if (u, i) not in train][:2] for u in test}
    hits = sum(test[u] in top2[u] for u in test)      # later clicks we predicted.
    coverage = len(set().union(*map(set, top2.values()))) / len(catalog)
    print(name, "hits:", hits, "coverage:", coverage)
